// Package pyrandom implements the subset of CPython's random.Random needed to reproduce its
// output exactly: a Mersenne Twister (MT19937) seeded the same way `random.Random(bytes)` is,
// and `choice`. This lets deterministic output generated by the original Python implementation
// be regenerated identically.
//
// It is NOT a cryptographically secure generator.
package pyrandom

import (
	"crypto/sha512"
	"encoding/binary"
	"math/bits"
	"slices"
)

const (
	stateSize  = 624
	shiftSize  = 397
	matrixA    = 0x9908b0df
	upperMask  = 0x80000000
	lowerMask  = 0x7fffffff
	wordLength = 32
)

// Random is a CPython-compatible Mersenne Twister generator.
type Random struct {
	state [stateSize]uint32
	index int
}

// New returns a generator seeded identically to CPython's `random.Random(seed)` when seed is a
// bytes object (seeding version 2): the seed is extended with its SHA-512 digest and interpreted
// as a big-endian integer.
func New(seed []byte) *Random {
	digest := sha512.Sum512(seed)
	material := slices.Concat(seed, digest[:])

	// CPython splits abs(int) into 32-bit words, least significant first.
	slices.Reverse(material)
	for len(material)%4 != 0 {
		material = append(material, 0)
	}
	key := make([]uint32, len(material)/4)
	for idx := range key {
		key[idx] = binary.LittleEndian.Uint32(material[idx*4:])
	}
	// Only as many words as the integer's bit length requires are used (minimum 1).
	for len(key) > 1 && key[len(key)-1] == 0 {
		key = key[:len(key)-1]
	}

	r := &Random{}
	r.initByArray(key)
	return r
}

func (r *Random) initGenrand(seed uint32) {
	r.state[0] = seed
	for idx := 1; idx < stateSize; idx++ {
		prev := r.state[idx-1]
		r.state[idx] = 1812433253*(prev^(prev>>30)) + uint32(idx) //nolint:gosec // idx < stateSize
	}
	r.index = stateSize
}

func (r *Random) initByArray(key []uint32) {
	r.initGenrand(19650218)
	i, j := 1, 0
	for k := max(stateSize, len(key)); k > 0; k-- {
		prev := r.state[i-1]
		r.state[i] = (r.state[i] ^ ((prev ^ (prev >> 30)) * 1664525)) + key[j] + uint32(j) //nolint:gosec // j < len(key)
		i++
		j++
		if i >= stateSize {
			r.state[0] = r.state[stateSize-1]
			i = 1
		}
		if j >= len(key) {
			j = 0
		}
	}
	for k := stateSize - 1; k > 0; k-- {
		prev := r.state[i-1]
		r.state[i] = (r.state[i] ^ ((prev ^ (prev >> 30)) * 1566083941)) - uint32(i) //nolint:gosec // i < stateSize
		i++
		if i >= stateSize {
			r.state[0] = r.state[stateSize-1]
			i = 1
		}
	}
	r.state[0] = upperMask
}

// Uint32 returns the next 32-bit output of the generator (CPython's genrand_uint32).
func (r *Random) Uint32() uint32 {
	if r.index >= stateSize {
		for idx := range stateSize {
			y := (r.state[idx] & upperMask) | (r.state[(idx+1)%stateSize] & lowerMask)
			next := r.state[(idx+shiftSize)%stateSize] ^ (y >> 1)
			if y&1 != 0 {
				next ^= matrixA
			}
			r.state[idx] = next
		}
		r.index = 0
	}
	y := r.state[r.index]
	r.index++
	y ^= y >> 11
	y ^= (y << 7) & 0x9d2c5680
	y ^= (y << 15) & 0xefc60000
	y ^= y >> 18
	return y
}

// GetRandBits is CPython's `getrandbits(k)` for 0 <= k <= 32.
func (r *Random) GetRandBits(k int) uint32 {
	if k <= 0 {
		return 0
	}
	if k > wordLength {
		panic("pyrandom: GetRandBits only supports up to 32 bits")
	}
	return r.Uint32() >> (wordLength - k)
}

// RandBelow returns a uniform value in [0, n), consuming generator output exactly as
// CPython's `_randbelow_with_getrandbits` does. n must fit in 32 bits.
func (r *Random) RandBelow(n int) int {
	if n <= 0 {
		return 0
	}
	k := bits.Len(uint(n))
	for {
		v := int(r.GetRandBits(k))
		if v < n {
			return v
		}
	}
}

// Choice returns a random element of seq as CPython's `choice` does.
func Choice[T any](r *Random, seq []T) T {
	return seq[r.RandBelow(len(seq))]
}
